import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.D7EuCHIT.js";const N=JSON.parse('{"title":"设置页挂载","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/settings-page.md","filePath":"plugins/settings-page.md","lastUpdated":1795336159000}'),c={name:"plugins/settings-page.md"};function T(r,t,_,E,A,i){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="设置页挂载" tabindex="-1">设置页挂载 <a class="header-anchor" href="#设置页挂载" aria-label="Permalink to &quot;设置页挂载&quot;">​</a></h1><p><code>LYRA_INTERFACE_SETTINGS_PAGE</code>（26，<code>plugin/settings_contracts.h</code>）让插件在宿主设置中挂载声明式页面。任何选中服务都可选实现；宿主枚举端点，不依赖私有名字。</p><h2 id="操作" tabindex="-1">操作 <a class="header-anchor" href="#操作" aria-label="Permalink to &quot;操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><code>LYRA_SETTINGS_INFO</code>(1)</td><td>页面元数据：TITLE、ENTRY_TITLE、COUNT、PAGE、REVISION，可选 PROMPT/NOTICE/INPUT/ENTRY_PARENT/INLINE</td></tr><tr><td><code>LYRA_SETTINGS_ROW</code>(2)</td><td>按 INDEX 取行：TITLE、DETAIL/BUTTON、FLAGS、VALUE/MIN/MAX/STEP</td></tr><tr><td><code>LYRA_SETTINGS_OPEN</code>(3)</td><td>重置导航到 PAGE 0；宿主端点要求 HANDLE 字段</td></tr><tr><td><code>LYRA_SETTINGS_BACK</code>(4)</td><td>根页返回 UNSUPPORTED，否则 OK</td></tr><tr><td><code>LYRA_SETTINGS_ACTIVATE</code>(5)</td><td>按当前行 INDEX（可选 SECONDARY/VALUE）触发</td></tr><tr><td><code>LYRA_SETTINGS_CONFIRM</code>(6)</td><td>ACCEPT 解决当前 prompt；BACK 先取消 prompt</td></tr><tr><td><code>LYRA_SETTINGS_HOST_CAPABILITIES</code>(7)</td><td>宿主端点返回支持的行与 prompt FLAGS</td></tr></tbody></table><h2 id="行类型-flags" tabindex="-1">行类型（FLAGS） <a class="header-anchor" href="#行类型-flags" aria-label="Permalink to &quot;行类型（FLAGS）&quot;">​</a></h2><p><code>TOGGLE</code>(1)、<code>CHECKED</code>(2)、<code>DISABLED</code>(4)、<code>GROUP_END</code>(8)、<code>SLIDER</code>(16)、<code>FORWARD</code>(32)；HOST_CAPABILITIES 另返回 <code>CAN_EDIT_PROMPT</code>(64)、<code>CAN_ACTIVATE_PROMPT</code>(128)、<code>CAN_LEAD_TEXT</code>(256)、<code>CAN_LEAD_RGBA</code>(512)、<code>CAN_MOUNT_ROWS</code>(1024)。</p><h2 id="约定" tabindex="-1">约定 <a class="header-anchor" href="#约定" aria-label="Permalink to &quot;约定&quot;">​</a></h2><ul><li>标量字段用 I64/F64，文本用含 NUL 的 UTF-8；数据借用至下一次 request；</li><li>未知必需字段拒绝，未知可选字段忽略；INFO 无副作用；</li><li><code>ENTRY_PARENT</code> 选择稳定的宿主分区路径，未知路径不回落首页；<code>INLINE</code> 非零时把根行内嵌到父页；</li><li>UI 负责滚动/滑块预览；插件负责校验、动作与持久化；</li><li>帧线程调用；CONFIRM 回显编辑后的 INPUT。</li></ul>',8)])])}const I=e(c,[["render",T]]);export{N as __pageData,I as default};
